-- combinaisoncouleur
-- id , idcouleur , referencecouleur
 
create table COMBINAISONCOULEUR(
    id varchar(255) constraint COMBINAISONCOULEUR_pk primary key ,
    idcouleur varchar(255) constraint COMBICOULEUR_idcouleur_fk references COULEUR(id) ,
    referencecouleur varchar(255)
);


create sequence seqCOMBINAISONCOULEUR
      minvalue 1
      maxvalue 999999999999
      start with 1
      increment by 1
      cache 20;
      
      

CREATE OR REPLACE FUNCTION getseqCOMBINAISONCOULEUR
   RETURN NUMBER
IS
   retour   NUMBER;
BEGIN
   SELECT seqCOMBINAISONCOULEUR.NEXTVAL INTO retour FROM DUAL;

   RETURN retour;
END;




CREATE VIEW v_reference_couleur
AS 
SELECT 
	c.REFERENCECOULEUR,
	LISTAGG(cc.val , ' - ') WITHIN GROUP (ORDER BY c.REFERENCECOULEUR) AS nomcouleur,
	LISTAGG(cc.desce , ' - ') WITHIN GROUP (ORDER BY c.REFERENCECOULEUR) AS codecouleur
FROM 
	COMBINAISONCOULEUR c 
    left join couleur cc on c.idcouleur = cc.id

GROUP BY 
	c.REFERENCECOULEUR;  

